/* Auto-playing mini animations for the "About this pattern" boxes. Each scene is generated by running the real algorithm,
   so every frame is correct. Row scenes show arrays with pointers; graph scenes show nodes and edges. */
(function(){
const R = (n, c, o) => Object.assign({ n, c: c.length ? c : ["·"] }, o || {});
const rg = (a, b) => { const o = []; for(let i = a; i <= b; i++) o.push(i); return o; };
const bits = (x, w) => x.toString(2).padStart(w, "0").split("");
const S = {};

S["Array / String"] = (() => { const a = [3, 1, 4, 1, 5, 9, 2, 6], f = []; let best = -1;
  a.forEach((x, i) => { const old = best; best = Math.max(best, x);
    f.push({ rows: [R("nums", a, { hot: [i], ok: rg(0, i - 1) }), R("best so far", [best])], note: x > old ? `${x} beats ${old < 0 ? "nothing yet" : old}, so best = ${x}` : `${x} does not beat ${best}, best stays ${best}` }); });
  f.push({ rows: [R("nums", a, { ok: rg(0, a.length - 1) }), R("best so far", [best])], note: `One pass, nothing rescanned: the answer is ${best}` });
  return { frames: f }; })();

S["Hash Map / Set"] = (() => { const a = [2, 7, 11, 15], t = 9, m = [], f = [];
  for(let i = 0; i < a.length; i++){ const need = t - a[i], hit = m.findIndex(e => e[0] === need);
    if(hit >= 0){ f.push({ rows: [R("nums", a, { hot: [i], ok: [m[hit][1]] }), R("map value→index", m.map(e => e[0] + "→" + e[1]), { ok: [hit] })], note: `need ${t}−${a[i]} = ${need}: found in the map at index ${m[hit][1]}, so the answer is [${m[hit][1]}, ${i}]` }); break; }
    f.push({ rows: [R("nums", a, { hot: [i] }), R("map value→index", m.map(e => e[0] + "→" + e[1]))], note: `need ${t}−${a[i]} = ${need}: not in the map yet, so remember ${a[i]}→${i}` }); m.push([a[i], i]); }
  return { frames: f }; })();

S["Dynamic Programming"] = (() => { const n = 6, dp = [1, 1], f = [];
  for(let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  const cells = i => dp.map((v, k) => k <= i ? v : "?");
  f.push({ rows: [R("ways to reach step i", cells(1), { ok: [0, 1] })], note: "Base cases: 1 way to stand at step 0, 1 way to reach step 1" });
  for(let i = 2; i <= n; i++) f.push({ rows: [R("ways to reach step i", cells(i), { hot: [i], ok: [i - 1, i - 2] })], note: `dp[${i}] = dp[${i - 1}] + dp[${i - 2}] = ${dp[i - 1]} + ${dp[i - 2]} = ${dp[i]}  (each answer reuses two smaller ones)` });
  return { frames: f }; })();

S["Graph"] = (() => { const N = { A: [180, 22], B: [90, 78], C: [270, 78], D: [40, 134], E: [140, 134], F: [230, 134], G: [320, 134] },
  E = [["A", "B"], ["A", "C"], ["B", "D"], ["B", "E"], ["C", "F"], ["C", "G"]], adj = {}; Object.keys(N).forEach(k => adj[k] = []); E.forEach(([a, b]) => { adj[a].push(b); adj[b].push(a); });
  const q = ["A"], seen = new Set(["A"]), done = new Set(), order = [], f = [];
  const st = cur => { const s = {}; q.forEach(x => s[x] = "queued"); done.forEach(x => s[x] = "seen"); if(cur) s[cur] = "cur"; return s; };
  f.push({ state: st(), rows: [R("queue", q.slice()), R("visit order", order.slice())], note: "Start: put A in the queue and mark it seen" });
  while(q.length){ const x = q.shift(); order.push(x); done.add(x);
    f.push({ state: st(x), rows: [R("queue", q.slice()), R("visit order", order.slice())], note: `Take ${x} from the front of the queue and visit it` });
    const nw = adj[x].filter(y => !seen.has(y)); if(nw.length){ nw.forEach(y => { seen.add(y); q.push(y); });
      f.push({ state: st(x), rows: [R("queue", q.slice()), R("visit order", order.slice())], note: `Add ${x}'s unseen neighbours ${nw.join(", ")} to the back: closest nodes are always visited first` }); } }
  f.push({ state: st(), rows: [R("queue", []), R("visit order", order.slice(), { ok: rg(0, order.length - 1) })], note: "Queue empty: every node visited once, level by level" });
  return { type: "graph", nodes: N, edges: E, frames: f }; })();

S["Math / Bit Manipulation"] = (() => { let n = 13, c = 0; const f = [];
  f.push({ rows: [R("n", bits(n, 4), { hot: [3] })], note: "Count the 1 bits in 13 = 1101. Idea: n & (n−1) clears the lowest 1 bit" });
  while(n){ const m = n & (n - 1), low = 3 - Math.log2(n & -n); c++;
    f.push({ rows: [R("n", bits(n, 4), { hot: [low] }), R("n − 1", bits(n - 1, 4)), R("n & (n−1)", bits(m, 4), { ok: [low] })], note: `Each step removes exactly one 1 bit, so the loop runs once per 1 bit: count = ${c}` }); n = m; }
  f.push({ rows: [R("n", bits(0, 4)), R("bits set", [c], { ok: [0] })], note: `n is 0, stop. 13 has ${c} one-bits, found in ${c} steps` });
  return { frames: f }; })();

S["Design"] = (() => { const cap = 3, c = [], f = [], show = (note, o) => f.push({ rows: [R("cache (oldest → newest)", c.slice(), o)], note });
  const put = k => { const i = c.indexOf(k); if(i >= 0) c.splice(i, 1); else if(c.length === cap){ show(`put(${k}): cache is full, so evict the oldest key ${c[0]}`, { bad: [0] }); c.shift(); } c.push(k); show(`put(${k}): ${k} is now the newest`, { hot: [c.length - 1] }); };
  const get = k => { const i = c.indexOf(k); c.splice(i, 1); c.push(k); show(`get(${k}): move ${k} to the newest end (it was just used)`, { hot: [c.length - 1] }); };
  put(1); put(2); put(3); get(1); put(4);
  f.push({ rows: [R("cache (oldest → newest)", c.slice(), { ok: rg(0, c.length - 1) })], note: "Hash map for O(1) lookup + ordered list for O(1) moves and evictions = LRU (Least Recently Used) cache" });
  return { frames: f }; })();

S["Backtracking"] = (() => { const a = [1, 2, 3], path = [], out = [], f = [];
  const snap = (note, o) => f.push({ rows: [R("current path", path.slice()), R("results so far", out.map(r => "[" + r.join(",") + "]"), o)], note });
  const go = s => { out.push(path.slice()); snap(`record [${path.join(",")}] as one answer`, { hot: [out.length - 1] });
    for(let i = s; i < a.length; i++){ path.push(a[i]); snap(`choose ${a[i]} and go deeper`); go(i + 1); const u = path.pop(); snap(`undo ${u}: back up and try the next choice`); } };
  go(0); f.push({ rows: [R("current path", []), R("results so far", out.map(r => "[" + r.join(",") + "]"), { ok: rg(0, out.length - 1) })], note: `All ${out.length} subsets found (2³ = 8): choose, explore, un-choose` });
  return { frames: f }; })();

S["Binary Search"] = (() => { const a = [1, 3, 5, 7, 9, 11, 13], t = 11, f = []; let lo = 0, hi = 6;
  const dead = () => [...rg(0, lo - 1), ...rg(hi + 1, a.length - 1)];
  while(lo <= hi){ const m = (lo + hi) >> 1;
    if(a[m] === t){ f.push({ rows: [R("sorted", a, { ok: [m], bad: dead(), p: { l: lo, m, r: hi } })], note: `a[${m}] = ${a[m]} equals the target ${t}: found` }); break; }
    f.push({ rows: [R("sorted", a, { hot: [m], bad: dead(), p: { l: lo, m, r: hi } })], note: a[m] < t ? `a[${m}] = ${a[m]} < ${t}: the target is to the right, drop the left half` : `a[${m}] = ${a[m]} > ${t}: the target is to the left, drop the right half` });
    if(a[m] < t) lo = m + 1; else hi = m - 1; }
  return { frames: f }; })();

S["Greedy"] = (() => { const a = [2, 3, 1, 1, 4], f = []; let far = 0;
  for(let i = 0; i < a.length && i <= far; i++){ far = Math.max(far, i + a[i]);
    f.push({ rows: [R("jump length", a, { hot: [i], ok: rg(0, Math.min(far, a.length - 1)).filter(k => k !== i) }), R("farthest reachable index", [far])], note: `At index ${i} we can reach ${i}+${a[i]} = ${i + a[i]}; farthest so far is ${far}` });
    if(far >= a.length - 1){ f.push({ rows: [R("jump length", a, { ok: rg(0, a.length - 1) }), R("farthest reachable index", [far])], note: `${far} ≥ last index ${a.length - 1}: we can reach the end. One local choice per step, no backtracking` }); break; } }
  return { frames: f }; })();

S["Binary Tree"] = (() => { const N = { 1: [180, 22], 2: [100, 78], 3: [260, 78], 4: [50, 134], 5: [150, 134] }, E = [[1, 2], [1, 3], [2, 4], [2, 5]], ch = { 1: [2, 3], 2: [4, 5], 3: [], 4: [], 5: [] },
  done = {}, f = [], hs = [];
  const snap = (cur, note) => { const s = {}, l = {}; Object.keys(done).forEach(k => { s[k] = "seen"; l[k] = k + ":" + done[k]; }); if(cur) s[cur] = "cur"; f.push({ state: s, lbl: l, rows: [R("heights found (post-order)", hs.slice())], note }); };
  const h = x => { snap(x, `Visit ${x}: first ask both children for their heights`); const hl = ch[x].map(h), v = 1 + Math.max(0, ...hl); done[x] = v; hs.push(x + ":" + v);
    snap(x, ch[x].length ? `Node ${x} = 1 + max(${hl.join(", ")}) = ${v}` : `Node ${x} has no children: height 1`); return v; };
  h(1); snap(null, "Each node's answer is built from its children's answers: height of the tree = 3");
  return { type: "graph", nodes: N, edges: E, frames: f }; })();

S["Stack / Monotonic Stack"] = (() => { const t = [73, 74, 75, 71, 69, 72, 76, 73], ans = t.map(() => 0), st = [], f = [];
  const snap = (i, note, o) => f.push({ rows: [R("temperature", t, Object.assign({ hot: [i] }, o || {})), R("stack (indices)", st.map(String)), R("days to wait", ans.slice())], note });
  t.forEach((x, i) => { while(st.length && t[st[st.length - 1]] < x){ const j = st.pop(); ans[j] = i - j; snap(i, `${x} is warmer than day ${j} (${t[j]}): pop it, answer = ${i} − ${j} = ${i - j}`, { ok: [j] }); }
    st.push(i); snap(i, `push day ${i}; the stack stays in decreasing temperature order`); });
  f.push({ rows: [R("temperature", t), R("stack (indices)", st.map(String)), R("days to wait", ans.slice(), { ok: rg(0, ans.length - 1) })], note: "Each day is pushed once and popped at most once: O(n)" });
  return { frames: f }; })();

S["Two Pointers"] = (() => { const a = [1, 2, 4, 6, 8, 11], t = 10, f = []; let l = 0, r = a.length - 1;
  while(l < r){ const s = a[l] + a[r], dead = [...rg(0, l - 1), ...rg(r + 1, a.length - 1)];
    f.push({ rows: [R("sorted", a, { hot: s === t ? [] : [l, r], ok: s === t ? [l, r] : [], bad: dead, p: { l, r } }), R("sum", [s + " vs " + t])], note: s === t ? `${a[l]} + ${a[r]} = ${t}: found the pair` : s < t ? `${s} < ${t}: too small, move the left pointer right` : `${s} > ${t}: too big, move the right pointer left` });
    if(s === t) break; if(s < t) l++; else r--; }
  return { frames: f }; })();

S["Sliding Window"] = (() => { const s = "abcabcbb".split(""), f = [], win = new Set(); let l = 0, best = 0;
  s.forEach((ch, r) => { while(win.has(ch)){ f.push({ rows: [R("string", s, { bad: [r], ok: rg(l, r - 1), p: { l, r } }), R("best length", [best])], note: `'${ch}' is already in the window: shrink from the left, drop '${s[l]}'` }); win.delete(s[l]); l++; }
    win.add(ch); best = Math.max(best, r - l + 1);
    f.push({ rows: [R("string", s, { ok: rg(l, r), p: { l, r } }), R("best length", [best])], note: `Add '${ch}': window "${s.slice(l, r + 1).join("")}" has length ${r - l + 1}` }); });
  return { frames: f }; })();

S["Heap"] = (() => { const a = [5, 1, 9, 3, 7, 8, 2], k = 3, h = [], f = [];
  const up = i => { while(i > 0){ const p = (i - 1) >> 1; if(h[p] <= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
  const down = i => { for(;;){ let m = i; const l = 2 * i + 1, r = l + 1; if(l < h.length && h[l] < h[m]) m = l; if(r < h.length && h[r] < h[m]) m = r; if(m === i) break; [h[m], h[i]] = [h[i], h[m]]; i = m; } };
  a.forEach((x, i) => { h.push(x); up(h.length - 1); let note = `push ${x}`;
    if(h.length > k){ const mn = h[0]; h[0] = h.pop(); down(0); note += `; size is ${k + 1} > ${k}, so pop the smallest (${mn})`; }
    f.push({ rows: [R("stream", a, { hot: [i], ok: rg(0, i - 1) }), R(`min-heap (size ≤ ${k})`, h.slice(), { hot: [0] })], note }); });
  f.push({ rows: [R("stream", a, { ok: rg(0, a.length - 1) }), R("the 3 largest", h.slice().sort((x, y) => y - x), { ok: [0, 1, 2] })], note: `The heap holds the ${k} largest values seen; its root is the ${k}rd largest. Each push or pop costs O(log k)` });
  return { frames: f }; })();

S["Matrix"] = (() => { const g = [[1, 2, 3], [4, 5, 6], [7, 8, 9]], path = [[0, 0], [0, 1], [0, 2], [1, 2], [2, 2], [2, 1], [2, 0], [1, 0], [1, 1]], f = [];
  path.forEach(([r, c], k) => { const rows = g.map((row, i) => R("row " + i, row, { hot: i === r ? [c] : [], ok: path.slice(0, k).filter(p => p[0] === i).map(p => p[1]) })); rows.push(R("order", path.slice(0, k + 1).map(([a, b]) => g[a][b])));
    f.push({ rows, note: k < 8 ? `Visit (${r}, ${c}) = ${g[r][c]}; keep going in the same direction until the edge or a visited cell, then turn right` : "Last cell: the whole grid is read in spiral order" }); });
  return { frames: f }; })();

S["Prefix Sum"] = (() => { const a = [3, 1, 4, 1, 5, 9], p = [0], f = [];
  a.forEach((x, i) => { p.push(p[i] + x); f.push({ rows: [R("nums", a, { hot: [i], ok: rg(0, i - 1) }), R("prefix (sum of first i)", p.slice(), { hot: [i + 1] })], note: `prefix[${i + 1}] = prefix[${i}] + ${x} = ${p[i + 1]}` }); });
  f.push({ rows: [R("nums", a, { hot: [2, 3, 4] }), R("prefix (sum of first i)", p.slice(), { ok: [5], bad: [2] })], note: `Sum of nums[2..4] = prefix[5] − prefix[2] = ${p[5]} − ${p[2]} = ${p[5] - p[2]}: any range in O(1)` });
  return { frames: f }; })();

S["Intervals"] = (() => { const iv = [[1, 3], [2, 6], [8, 10], [9, 12], [15, 18]], lab = x => x[0] + "–" + x[1], f = [], merged = []; let cur = iv[0].slice();
  const snap = (i, note, o) => f.push({ rows: [R("sorted by start", iv.map(lab), Object.assign({ hot: [i] }, o || {})), R("current", [lab(cur)], { hot: [0] }), R("merged", merged.map(lab))], note });
  snap(0, "Sort by start, then sweep. Start with the first interval as current");
  for(let i = 1; i < iv.length; i++){ const s = iv[i][0], e = iv[i][1];
    if(s <= cur[1]){ const was = cur[1]; cur[1] = Math.max(cur[1], e); snap(i, `${s} ≤ ${was}: overlaps, extend current to ${lab(cur)}`); }
    else { const was = cur[1]; merged.push(cur.slice()); cur = [s, e]; snap(i, `${s} > ${was}: no overlap, save the finished interval and start ${lab(cur)}`); } }
  merged.push(cur.slice()); f.push({ rows: [R("sorted by start", iv.map(lab), { ok: rg(0, 4) }), R("merged", merged.map(lab), { ok: rg(0, merged.length - 1) })], note: "Finish: save the last one. One pass after sorting" });
  return { frames: f }; })();

S["Union Find / Segment Tree"] = (() => { const n = 6, p = rg(0, n - 1), f = [], find = x => { while(p[x] !== x) x = p[x]; return x; }; let groups = n;
  const snap = (note, hot) => f.push({ rows: [R("item", rg(0, n - 1)), R("parent", p.slice(), { hot: hot || [] }), R("groups", [groups])], note });
  snap("Every item starts as its own group (its own parent)");
  [[0, 1], [2, 3], [1, 3], [4, 5], [0, 3]].forEach(([a, b]) => { const ra = find(a), rb = find(b);
    if(ra === rb){ snap(`union(${a}, ${b}): same root ${ra} already, nothing to do`, [a, b]); return; }
    p[ra] = rb; groups--; snap(`union(${a}, ${b}): join root ${ra} under root ${rb}, groups = ${groups}`, [ra]); });
  return { frames: f }; })();

S["Linked List"] = (() => { const v = [1, 2, 3, 4], nx = [1, 2, 3, null], f = []; let prev = -1, cur = 0;
  const tl = i => i == null ? "None" : String(v[i]);
  const snap = (note, p, hot, ok) => { const pp = {}; Object.keys(p).forEach(k => { if(p[k] != null && p[k] >= 0) pp[k] = p[k]; });
    f.push({ rows: [R("node", v, { p: pp, ok: ok || [] }), R("node.next →", nx.map(tl), { hot: hot || [] })], note }); };
  snap("Reverse in place: every node's next pointer must point backwards", { cur });
  while(cur != null){ const n = nx[cur];
    snap(`nxt = cur.next: save node ${tl(n)} before we overwrite the pointer`, { prev, cur, nxt: n }, [cur]);
    nx[cur] = prev < 0 ? null : prev; snap(`cur.next = prev: node ${v[cur]} now points to ${tl(nx[cur])}`, { prev, cur }, [cur]);
    prev = cur; cur = n; snap(`move on: prev = ${v[prev]}${cur == null ? ", cur = None" : ", cur = " + v[cur]}`, { prev, cur }); }
  snap("cur is None: return prev. The list now reads 4 → 3 → 2 → 1", { prev }, [], rg(0, 3));
  return { frames: f }; })();

S["Sorting"] = (() => { const a = [5, 2, 4, 6, 1, 3], f = [];
  const snap = (i, hot, note) => f.push({ rows: [R("array", a.slice(), { ok: rg(0, i - 1).filter(k => !hot.includes(k)), hot })], note });
  for(let i = 1; i < a.length; i++){ const key = a[i]; let j = i - 1; snap(i, [i], `Take ${key} and insert it into the sorted part on its left`);
    while(j >= 0 && a[j] > key){ a[j + 1] = a[j]; snap(i, [j + 1], `${a[j]} > ${key}: shift ${a[j]} one place right`); j--; }
    a[j + 1] = key; snap(i + 1, [j + 1], `drop ${key} into its place; the left part is sorted`); }
  f.push({ rows: [R("array", a.slice(), { ok: rg(0, a.length - 1) })], note: "Sorted. Insertion sort is O(n²) but fast on nearly sorted data" });
  return { frames: f }; })();

S["Trie"] = (() => { const N = { r: [150, 20], c: [150, 68], a: [90, 116], o: [210, 116], t: [50, 164], q: [130, 164], w: [210, 164] }, E = [["r", "c"], ["c", "a"], ["c", "o"], ["a", "t"], ["a", "q"], ["o", "w"]],
  words = [["cat", ["r", "c", "a", "t"]], ["car", ["r", "c", "a", "q"]], ["cow", ["r", "c", "o", "w"]]], made = new Set(["r"]), ends = {}, f = [], ch = { r: "·", c: "c", a: "a", o: "o", t: "t", q: "r", w: "w" }, nm = { t: "cat", q: "car", w: "cow" };
  const snap = (cur, note) => { const s = {}, l = {}; made.forEach(k => { s[k] = "seen"; l[k] = ch[k] + (ends[k] ? "*" : ""); }); if(cur) s[cur] = "cur"; f.push({ state: s, lbl: l, rows: [R("words stored", Object.keys(ends).map(k => nm[k]))], note }); };
  snap(null, "An empty trie: just the root");
  words.forEach(([w, path]) => { path.slice(1).forEach((k, i) => { const had = made.has(k); made.add(k); snap(k, `insert "${w}": '${w[i]}' ${had ? "already exists, follow it (shared prefix)" : "is new, create a child"}`); }); ends[path[path.length - 1]] = 1; snap(null, `mark the last letter (*) as the end of "${w}"`); });
  return { type: "graph", ghost: true, nodes: N, edges: E, frames: f }; })();

S["Binary Search Tree"] = (() => { const N = { 8: [180, 20], 3: [100, 76], 10: [260, 76], 1: [60, 132], 6: [140, 132], 14: [300, 132], 4: [110, 188], 7: [170, 188] }, E = [[8, 3], [8, 10], [3, 1], [3, 6], [10, 14], [6, 4], [6, 7]], f = [], seen = {}, t = 7;
  const lc = { 8: [3, 10], 3: [1, 6], 6: [4, 7], 10: [null, 14], 1: [], 14: [], 4: [], 7: [] };
  let x = 8; for(;;){ const s = Object.assign({}, seen); s[x] = "cur";
    f.push({ state: s, rows: [R("looking for", [t])], note: x === t ? `${x} = ${t}: found` : `${t} ${x > t ? "<" : ">"} ${x}: everything ${x > t ? "bigger" : "smaller"} is on the other side, go ${x > t ? "left" : "right"}` });
    if(x === t) break; seen[x] = "seen"; x = lc[x][x > t ? 0 : 1]; }
  f.push({ state: Object.assign({}, seen, { [t]: "seen" }), rows: [R("looking for", [t], { ok: [0] })], note: "Four nodes visited instead of eight: each step discards a whole sub-tree (O(height))" });
  return { type: "graph", nodes: N, edges: E, frames: f }; })();

S["Queue"] = (() => { const q = [], f = [], W = 3000, snap = (note, o) => f.push({ rows: [R("queue (oldest → newest)", q.slice(), o), R("count in window", [q.length])], note });
  [1, 100, 3001, 3002].forEach(t => { q.push(t); snap(`ping(${t}): add to the back. Valid window is [${t - W}, ${t}]`, { hot: [q.length - 1] });
    const exp = []; q.forEach((x, i) => { if(x < t - W) exp.push(i); }); if(exp.length){ snap(`${q[0]} < ${t - W}: expired, take it off the front`, { bad: exp, hot: [q.length - 1] }); q.splice(0, exp.length); snap(`removed; ${q.length} requests are still inside the window`, { ok: rg(0, q.length - 1) }); } });
  return { frames: f }; })();

S["Divide & Conquer"] = (() => { const L = [["6 2 8 4 1 7"], ["6 2 8", "4 1 7"], ["6 2", "8", "4 1", "7"], ["6", "2", "8", "4", "1", "7"], ["2 6", "8", "1 4", "7"], ["2 6 8", "1 4 7"], ["1 2 4 6 7 8"]],
  N = ["Start with the whole array", "Split in half", "Keep splitting", "Single items are already sorted", "Merge neighbours into sorted pairs", "Merge again (two sorted lists, take the smaller front each time)", "One last merge: sorted. Splitting is free, merging costs O(n) per level over log n levels = O(n log n)"];
  return { frames: L.map((g, i) => ({ rows: [R(i < 4 ? "divide" : "combine", g, i === 6 ? { ok: [0] } : {})], note: N[i] })) }; })();

S["Kadane's Algorithm"] = (() => { const a = [-2, 1, -3, 4, -1, 2, 1, -5, 4], f = []; let cur = a[0], best = a[0], s = 0, bs = 0, be = 0;
  f.push({ rows: [R("nums", a, { hot: [0] }), R("best ending here", [cur]), R("best overall", [best])], note: "Start with the first item" });
  for(let i = 1; i < a.length; i++){ const ext = cur + a[i]; if(a[i] > ext){ cur = a[i]; s = i; } else cur = ext; if(cur > best){ best = cur; bs = s; be = i; }
    f.push({ rows: [R("nums", a, { hot: [i], ok: rg(s, i - 1) }), R("best ending here", [cur]), R("best overall", [best])], note: `${a[i]}: extend (${ext}) or start fresh (${a[i]})? take ${cur}. Best overall = ${best}` }); }
  f.push({ rows: [R("nums", a, { ok: rg(bs, be) }), R("best overall", [best], { ok: [0] })], note: `Best sub-array is [${a.slice(bs, be + 1).join(", ")}] with sum ${best}, in one pass` });
  return { frames: f }; })();

window.TOPIC_VIS = S;

/* ---- renderer ---- */
const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
function rowHtml(r){
  const h = r.hot || [], o = r.ok || [], b = r.bad || [], p = r.p || {};
  return `<div class="vrow"><span class="vn">${esc(r.n)}</span><div class="vcells">${r.c.map((x, i) => {
    const pl = Object.keys(p).filter(k => p[k] === i).join(",");
    return `<div class="vcol"><span class="vc${h.includes(i) ? " hot" : ""}${o.includes(i) ? " ok" : ""}${b.includes(i) ? " bad" : ""}">${esc(x)}</span><span class="vp">${pl}</span></div>`; }).join("")}</div></div>`;
}
function graphHtml(sc, fr){
  const N = sc.nodes, ids = Object.keys(N), W = 360, H = Math.max.apply(null, ids.map(k => N[k][1])) + 28, stt = fr.state || {};
  const edges = sc.edges.map(([a, b]) => { const off = sc.ghost && (!stt[a] || !stt[b]); return `<line class="ve${off ? " off" : ""}" x1="${N[a][0]}" y1="${N[a][1]}" x2="${N[b][0]}" y2="${N[b][1]}"/>`; }).join("");
  const nodes = ids.map(k => { const s = stt[k] || (sc.ghost ? "off" : "n"), l = (fr.lbl && fr.lbl[k]) || k;
    return `<g class="vg ${s}"><circle cx="${N[k][0]}" cy="${N[k][1]}" r="16"/><text x="${N[k][0]}" y="${N[k][1] + 4}" text-anchor="middle">${esc(l)}</text></g>`; }).join("");
  return `<svg viewBox="0 0 ${W} ${H}" class="vsvg" role="img" aria-label="animated diagram">${edges}${nodes}</svg>`;
}
window.mountTopicVis = function(box, sc){
  const fr = sc.frames; let i = 0, timer = null, on = false;
  box.innerHTML = `<div class="vstage"></div><p class="vnote"></p><div class="vbar"><button type="button" class="vbtn" aria-label="Pause or play">⏸</button><span class="vct"></span></div>`;
  const st = box.querySelector(".vstage"), nt = box.querySelector(".vnote"), ct = box.querySelector(".vct"), bt = box.querySelector(".vbtn");
  const draw = () => { const f = fr[i]; st.innerHTML = (sc.type === "graph" ? graphHtml(sc, f) : "") + f.rows.map(rowHtml).join(""); nt.textContent = f.note; ct.textContent = (i + 1) + " / " + fr.length; };
  const tick = () => { i = (i + 1) % fr.length; draw(); timer = setTimeout(tick, i === fr.length - 1 ? 2600 : 1500); };
  const play = () => { if(on) return; on = true; bt.textContent = "⏸"; timer = setTimeout(tick, 1400); };
  const stop = () => { on = false; clearTimeout(timer); bt.textContent = "▶"; };
  bt.onclick = () => on ? stop() : play();
  draw();
  return { play, stop };
};
})();
